CREATE proc [dbo].[UspGetCustomerLedger] @From as datetime, @To as Datetime, @CustId as text as Declare @Cheque as nvarchar(50); select CONVERT(VARCHAR(11),@From,106) as [From],CONVERT(VARCHAR(11),@To,106) as [To],[dbo].GetChequeNo(sl.VN) as Cheque,v.CustId,v.Customer,sl.Date,[dbo].funcGetVoucherDescVendor(sl.VN,sl.VoucherId) as VoucherType,sl.VN as PINO,((select isnull(sum(Amount),0) from CustomerLedger where CustId = v.CustId and [Type] = 'C' and Date < @From) -(select isnull(sum(Amount),0) from CustomerLedger where  CustId = v.CustId and [Type] = 'D' and Date < @From)) as OpenBalance ,(select isnull(sum(Amount),0) from CustomerLedger where Id = sl.Id and [Type] = 'D') as Debit,(select isnull(sum(Amount),0) from CustomerLedger where Id = sl.Id and [Type] = 'C') as Credit,(((select isnull(sum(Amount),0) from CustomerLedger where  CustId = v.CustId and [Type] = 'C' and Date < @From) -(select isnull(sum(Amount),0) from CustomerLedger where  CustId = v.CustId and [Type] = 'D' and Date < @From)) +(select isnull(sum(Amount),0) from CustomerLedger where Id = sl.Id and [Type] = 'C') -(select isnull(sum(Amount),0) from CustomerLedger where Id = sl.Id and [Type] = 'D')) as Balance from Customer v inner join CustomerLedger sl on v.CustId = sl.CustId inner join Split(@CustId,',') sp on sp.items = v.CustId where sl.Date between @From and @To